        if previous != self.selected() {
            cx.emit(EditorCompletionEvent::SelectionChanged);
        }
        cx.notify()
    }
    fn changed(&mut self, w: &Window, cx: &mut Context<Self>) {
        self.cursor = true;
        self.follow_caret = true;
        self.layout = None;
        w.notify_text_input_changed(&self.focus);
        cx.emit(EditEvent::Changed);
        cx.notify()
    }
    fn snapshot(&self) -> Snapshot {
        Snapshot {
            text: self.value.clone(),
            anchor: self.anchor,
            caret: self.caret,
        }
    }
    fn edit(
        &mut self,
        range: Option<Range<usize>>,
        text: &str,
        composition: bool,
        sel: Option<Range<usize>>,
        w: &Window,
        cx: &mut Context<Self>,
    ) {
        if self.disabled || self.read_only {
            return;
        }
        if self.ghost_fade_out.is_some() {
            self.set_ghost("", cx);
        }
        let range = range
            .map(|r| self.bytes(r))
            .or_else(|| self.marked.clone())
            .unwrap_or_else(|| self.selected());
        let text = self.normalize(text);
        if self.marked.is_none() {
            self.history.push(self.snapshot());
            if self.history.len() > 100 {
                self.history.remove(0);
            }
            self.redo.clear()
        }
        self.value.replace_range(range.clone(), &text);
        let end = range.start + text.len();
        self.caret = end;
        self.anchor = end;
        self.marked = (composition && !text.is_empty()).then_some(range.start..end);
        if composition && let Some(sel) = sel {
            self.anchor = range.start + from_utf16(&text, sel.start);
            self.caret = range.start + from_utf16(&text, sel.end)
        }
        self.changed(w, cx)
    }
    fn undo(&mut self, forward: bool, w: &Window, cx: &mut Context<Self>) {
        if self.read_only {
            return;
        }
        let old = if forward {
            self.redo.pop()
        } else {
            self.history.pop()
        };
        if let Some(old) = old {
            let current = self.snapshot();
            if forward {
                self.history.push(current)
            } else {
                self.redo.push(current)
            }
            self.value = old.text;
            self.anchor = old.anchor;
            self.caret = old.caret;
            self.marked = None;
            self.changed(w, cx)
        }
    }
    fn boundary(&self, right: bool, word: bool) -> usize {
        if right {
            let tail = &self.value[self.caret..];
            self.caret
                + if word {
                    tail.split_word_bound_indices()
                        .next()
                        .map_or(0, |(_, s)| s.len())
                } else {
                    tail.graphemes(true).next().map_or(0, str::len)
                }
        } else {
            let head = &self.value[..self.caret];
            if word {
                head.split_word_bound_indices()
                    .next_back()
                    .map_or(0, |(i, _)| i)
            } else {
                head.grapheme_indices(true)
                    .next_back()
                    .map_or(0, |(i, _)| i)
            }
        }
    }
    /// Accept an available suggestion through the normal edit/undo path.
    pub fn accept_ghost(&mut self, word: bool, w: &Window, cx: &mut Context<Self>) -> bool {
        if self.disabled
            || self.marked.is_some()
            || self.ghost_preview
            || self.ghost_fade_out.is_some()
            || self.ghost.is_empty()
            || !self.selected().is_empty()
            || self.caret != self.value.len()
        {
            return false;
        }
        let text = if word {
            let mut length = 0;
            for part in self.ghost.split_word_bounds() {
                length += part.len();
                if !part.chars().all(char::is_whitespace) {
                    break;
                }
            }
            self.ghost[..length].to_owned()
        } else {
            self.ghost.to_string()
        };
        let remaining = self.ghost[text.len()..].to_owned();
        self.set_ghost(remaining, cx);
        cx.emit(EditorCompletionEvent::Accepted {
            text: text.clone().into(),
            word,
        });
        self.edit(None, &text, false, None, w, cx);
        true
    }
    fn key(&mut self, e: &KeyDownEvent, w: &mut Window, cx: &mut Context<Self>) {
        if self.disabled || self.marked.is_some() {
            return;
        }
        let m = e.keystroke.modifiers;
        let k = e.keystroke.key.as_str();
        let cmd = m.platform || m.control;
        if is_command_submit(
            self.command_submit,
            self.marked.is_some(),
            k,
            cmd,
            m.shift,
            m.alt,
        ) {
            cx.emit(EditorShortcutEvent::CommandSubmit);
            w.prevent_default();
            cx.stop_propagation();
            return;
        }
        let r = self.selected();
        if !self.ghost_preview
            && self.ghost_fade_out.is_none()
            && !self.ghost.is_empty()
            && r.is_empty()
            && r.end == self.value.len()
        {
            let word = k == "right" && (m.platform || m.control || m.alt) && !m.shift;
            if (k == "tab" && !m.shift && !m.alt && !m.control && !m.platform) || word {
                self.accept_ghost(word, w, cx);
                w.prevent_default();
                cx.stop_propagation();
                return;
            }
            if k == "escape" {
                cx.emit(EditorCompletionEvent::Dismissed);
                cx.notify();
                w.prevent_default();
                cx.stop_propagation();
                return;
            }
        }
        match k {
            "a" if cmd => self.select_all(w, cx),
            "z" if cmd => self.undo(m.shift, w, cx),
            "y" if cmd => self.undo(true, w, cx),
            "c" | "x" if cmd => {
                if !r.is_empty() && self.mode != InputMode::Password {
                    cx.write_to_clipboard(ClipboardItem::new_string(self.value[r].to_owned()));
                    if k == "x" {
                        self.edit(None, "", false, None, w, cx)
                    }
                }
            }
            "v" if cmd && !cfg!(target_family = "wasm") => {
                if let Some(text) = cx.read_from_clipboard().and_then(|v| v.text()) {
                    self.edit(None, &text, false, None, w, cx)
                }
            }
            "left" | "right" => {
                let right = k == "right";
                let to = if !m.shift && !r.is_empty() {
                    if right { r.end } else { r.start }
                } else if m.platform {
                    self.line_edge(right)
                } else {
                    self.boundary(right, m.alt || m.control)
                };
                self.select(to, m.shift, w, cx)
            }
            "home" | "end" => {
                let end = k == "end";
                let to = if cmd {
                    if end { self.value.len() } else { 0 }
                } else {
                    self.line_edge(end)
                };
                self.select(to, m.shift, w, cx)
            }
            "backspace" | "delete" if !self.read_only => {
                if r.is_empty() {
                    self.anchor = self.boundary(k == "delete", m.alt || m.control)
                }
                if !self.selected().is_empty() {
                    self.edit(None, "", false, None, w, cx)
                }
            }
            "up" | "down" if self.mode == InputMode::Combobox => {
                cx.emit(EditEvent::Navigate(k == "down"))
            }
            "up" | "down" if self.mode.multiline() => {
                if let Some(l) = &self.layout {
                    let mut p = l.at(self.caret);
                    p.y += if k == "down" {
                        l.line * 1.5
                    } else {
                        -l.line * 0.5
                    };
                    self.select(l.hit(p), m.shift, w, cx)
                }
            }
            "enter"
                if self.mode == InputMode::Multi
                    || (self.mode == InputMode::InlineMulti && m.shift) =>
            {
                self.edit(None, "\n", false, None, w, cx)
            }
            "enter" => cx.emit(EditEvent::Submitted),
            "escape" => cx.emit(EditEvent::Escape),
            _ => return,
        }
        w.prevent_default();
        cx.stop_propagation()
    }
    fn line_edge(&self, end: bool) -> usize {
        if end {
            self.value[self.caret..]
                .find('\n')
                .map_or(self.value.len(), |n| self.caret + n)
        } else {
            self.value[..self.caret].rfind('\n').map_or(0, |i| i + 1)
        }
    }
}
impl EntityInputHandler for Editor {
    fn text_for_range(
        &mut self,
        r: Range<usize>,
        actual: &mut Option<Range<usize>>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<String> {
        let r = self.bytes(r);
        *actual = Some(self.units(r.clone()));
        Some(self.value[r].to_owned())
    }
    fn selected_text_range(
        &mut self,
        _: bool,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<UTF16Selection> {
        Some(UTF16Selection {
            range: self.units(self.selected()),
            reversed: self.anchor > self.caret,
        })
    }
    fn text_length_utf16(&mut self, _: &mut Window, _: &mut Context<Self>) -> Option<usize> {
        Some(self.value.encode_utf16().count())
    }
    fn set_selected_text_range(&mut self, r: Range<usize>, w: &mut Window, cx: &mut Context<Self>) {
        let r = self.bytes(r);
        self.anchor = r.start;
        self.select(r.end, true, w, cx)
    }
    fn marked_text_range(&self, _: &mut Window, _: &mut Context<Self>) -> Option<Range<usize>> {
        self.marked.clone().map(|r| self.units(r))
    }
    fn unmark_text(&mut self, w: &mut Window, cx: &mut Context<Self>) {
        let had_composition = self.marked.take().is_some();
        w.notify_text_input_changed(&self.focus);
        if had_composition {
            cx.emit(EditorCompletionEvent::CompositionEnded);
        }
        cx.notify()
    }
    fn replace_text_in_range(
        &mut self,
        r: Option<Range<usize>>,
        s: &str,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.edit(r, s, false, None, w, cx)
    }
    fn replace_and_mark_text_in_range(
        &mut self,
        r: Option<Range<usize>>,
        s: &str,
        sel: Option<Range<usize>>,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.edit(r, s, true, sel, w, cx)
    }
    fn bounds_for_range(
        &mut self,
        r: Range<usize>,
        _: Bounds<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<Bounds<Pixels>> {
        self.layout
            .as_ref()?
            .rects(self.bytes(r))
            .into_iter()
            .next()
    }
    fn selection_bounds_for_range(
        &mut self,
        r: Range<usize>,
        _: Bounds<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Vec<Bounds<Pixels>> {
        self.layout
            .as_ref()
            .map_or_else(Vec::new, |l| l.rects(self.bytes(r)))
    }
    fn character_index_for_point(
        &mut self,
        p: Point<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<usize> {
        let n = self.layout.as_ref()?.hit(p).min(self.value.len());
        Some(self.units(n..n).start)
    }
    fn accepts_text_input(&self, _: &mut Window, _: &mut Context<Self>) -> bool {
        !self.disabled && !self.read_only
    }
    fn text_input_configuration(
        &mut self,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> TextInputConfiguration {
        TextInputConfiguration {
            autocorrect: false,
            suggestions: self.mode != InputMode::Password,
            input_action: match self.mode {
                InputMode::Multi => TextInputAction::Enter,
                InputMode::Combobox | InputMode::Search => TextInputAction::Search,
                _ => TextInputAction::Done,
            },
            ..Default::default()
        }
    }
}
impl Editor {
    fn paint(&mut self, b: Bounds<Pixels>, w: &mut Window, cx: &mut Context<Self>) {
        let focused = self.focus.is_focused(w);
        let reduced = disabled_motion(cx);
        let now = Instant::now();
        if self
            .ghost_fade_out
            .is_some_and(|started| reduced || now.duration_since(started).as_secs_f32() >= 0.11)
        {
            self.ghost = "".into();
            self.ghost_chunks.clear();
            self.ghost_fade_out = None;
        }
        let p = Paint::get(cx);
        let blank = self.value.is_empty();
        let masked = self.mode == InputMode::Password && !self.revealed && !blank;
        let mask = if masked {
            self.value
                .grapheme_indices(true)
                .map(|(i, _)| i)
                .chain(std::iter::once(self.value.len()))
                .collect::<Vec<_>>()
        } else {
            vec![]
        };
        let show_ghost = (focused || self.ghost_preview || self.ghost_fade_out.is_some())
            && !blank
            && !masked
            && self.marked.is_none()
            && self.selected().is_empty()
            && self.caret == self.value.len()
            && !self.ghost.is_empty();
        let text: SharedString = if show_ghost {
            format!("{}{}", self.value, self.ghost).into()
        } else if blank {
            self.committed_label
                .clone()
                .unwrap_or_else(|| self.placeholder.clone())
        } else if masked {
            "•".repeat(mask.len() - 1).into()
        } else {
            self.value.clone().into()
        };
        let mut run = w.text_style().to_run(text.len());
        run.color = if (blank && self.committed_label.is_none()) || self.disabled {
            p.secondary
        } else {
            p.ink
        };
        let line = px(self.font_size + 7.);
        let multi = self.mode.multiline();
        let styled = if show_ghost {
            let mut base = run.clone();
            base.len = self.value.len();
            let mut runs = vec![base];
            let fade = self.ghost_fade_out.map_or(1., |started| {
                1. - ease((now.duration_since(started).as_secs_f32() / 0.11).clamp(0., 1.))
            });
            let mut animating = self.ghost_fade_out.is_some();
            if self
                .ghost_chunks
                .iter()
                .map(|chunk| chunk.len)
                .sum::<usize>()
                == self.ghost.len()
            {
                for chunk in &self.ghost_chunks {
                    let progress = if reduced {
                        1.
                    } else {
                        (now.duration_since(chunk.started).as_secs_f32() / 0.14).clamp(0., 1.)
                    };
                    animating |= progress < 1.;
                    let mut suffix = run.clone();
                    suffix.len = chunk.len;
                    suffix.color = p.faint.opacity(ease(progress) * fade);
                    runs.push(suffix);
                }
            } else {
                let mut suffix = run.clone();
                suffix.len = self.ghost.len();
                suffix.color = p.faint.opacity(fade);
                runs.push(suffix);
            }
            if animating && !reduced && w.is_visible() {
                w.request_animation_frame();
            }
            Some(runs)
        } else if !blank && !masked {
            self.run_styler.as_ref().map(|f| f(&text, &run))
        } else {
            None
        };
        let has_run_backgrounds = styled
            .as_ref()
            .is_some_and(|runs| runs.iter().any(|run| run.background_color.is_some()));
        let rows = w
            .text_system()
            .shape_text(
                text,
                px(self.font_size),
                styled.as_deref().unwrap_or(std::slice::from_ref(&run)),
                multi.then_some(b.size.width.max(px(1.))),
                None,
            )
            .unwrap_or_default()
            .into_vec();
        let height = rows
            .iter()
            .fold(px(0.), |sum, row| sum + row.size(line).height);
        let top = if multi {
            b.top()
        } else {
            b.top() + (b.size.height - line) * 0.5
        };
        let longest = rows
            .iter()
            .map(|row| row.size(line).width)
            .max()
            .unwrap_or(px(0.));
        let inset = if self.center_text && !multi {
            ((b.size.width - longest) / 2.).max(px(0.))
        } else {
            px(0.)
        };
        let origin = point(b.left() + inset, top);
        let mut layout = Layout {
            bounds: b,
            origin,
            rows,
            mask,
            line,
        };
        let pt = layout.at(self.caret) - origin;
        if self.follow_caret {
            let keep = |scroll: Pixels, pos: Pixels, room: Pixels| {
                scroll.min(pos).max(pos - room).max(px(0.))
            };
            self.scroll.x = if multi {
                px(0.)
            } else {
                keep(self.scroll.x, pt.x, b.size.width - px(2.))
            };
            self.scroll.y = keep(self.scroll.y, pt.y, (b.size.height - line).max(px(0.)));
            self.follow_caret = false
        }
        // A newly mounted flex child can first paint at width zero; never retain
        // that transient horizontal offset once the real width is known.
        self.scroll.x = self
            .scroll
            .x
            .min((longest + px(2.) - b.size.width).max(px(0.)));
        self.scroll.y = self.scroll.y.min((height - b.size.height).max(px(0.)));
        if self.mode == InputMode::Multi
            && let Some(host) = cx.try_global::<EditorScrollRegion>()
        {
            (host.0)(
                b,
                self.scroll.y > px(0.),
                self.scroll.y + b.size.height < height,
            );
        }
        layout.origin -= self.scroll;
        w.with_content_mask(Some(ContentMask { bounds: b }), |w| {
            if has_run_backgrounds {
                let mut pos = layout.origin;
                for row in &layout.rows {
                    let _ = row.paint_background(pos, line, TextAlign::Left, None, w, cx);
                    pos.y += row.size(line).height;
                }
            }
            if focused && !self.selected().is_empty() {
                for rect in layout.rects(self.selected()) {
                    w.paint_quad(fill(rect, p.ink.opacity(0.19)))
                }
            }
            let mut pos = layout.origin;
            for row in &layout.rows {
                let _ = row.paint(pos, line, TextAlign::Left, None, w, cx);
                pos.y += row.size(line).height;
            }
            if let Some(mark) = &self.marked {
                for rect in layout.rects(mark.clone()) {
                    w.paint_quad(fill(
                        Bounds::new(
                            point(rect.left(), rect.bottom() - px(1.)),
                            size(rect.size.width, px(1.)),
                        ),
                        p.ink,
                    ))
                }
            }
            if focused
                && self.cursor
                && self.selected().is_empty()
                && self.committed_label.is_none()
            {
                let caret = layout.at(self.caret);
                w.paint_quad(fill(
                    Bounds::new(caret + point(px(0.), px(2.)), size(px(1.), line - px(4.))),
                    p.ink,
                ))
            }
        });
        self.layout = Some(layout);
        if !self.disabled {
            w.handle_input(&self.focus, ElementInputHandler::new(b, cx.entity()), cx)
        }
    }
}
impl Render for Editor {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let entity = cx.entity();
        let name = self.label.clone();
        let role = match self.mode {
            InputMode::Password => Role::PasswordInput,
            InputMode::Multi | InputMode::InlineMulti => Role::MultilineTextInput,
            InputMode::Search => Role::SearchInput,
            InputMode::Combobox => Role::ComboBox,
            _ => Role::TextInput,
        };
        div()
            .id("editor")
            .debug_selector(move || name.to_string())
            .track_focus(&self.focus)
            .tab_stop(!self.disabled)
            .role(role)
            .aria_label(self.label.clone())
            .aria_description(self.description.clone())
            .aria_placeholder(self.placeholder.clone())
            .when_some(self.expanded, |e, open| e.aria_expanded(open))
            .when(self.mode != InputMode::Password, |e| {
                e.aria_value(
                    self.committed_label
                        .clone()
                        .unwrap_or_else(|| self.value.clone().into()),
                )
            })
            .size_full()
            .min_w_0()
            .overflow_hidden()
            .cursor(CursorStyle::IBeam)
            .on_key_down(cx.listener(Self::key))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|s, e: &MouseDownEvent, w, cx| {
                    if s.disabled {
                        return;
                    }
                    s.focus(w, cx);
                    w.request_virtual_keyboard();
                    let pos = s
                        .layout
                        .as_ref()
                        .map_or(0, |l| l.hit(e.position))
                        .min(s.value.len());
                    if e.click_count >= 3 {
                        s.select_all(w, cx)
                    } else if e.click_count == 2 {
                        let r = s
                            .value
                            .split_word_bound_indices()
                            .find(|(i, t)| pos < *i + t.len())
                            .map(|(i, t)| i..i + t.len())
                            .unwrap_or(pos..pos);
                        s.anchor = r.start;
                        s.select(r.end, true, w, cx)
                    } else {
                        s.select(pos, e.modifiers.shift, w, cx)
                    }
                    s.dragging = true;
                }),
            )
            .on_mouse_move(cx.listener(|s, e: &MouseMoveEvent, w, cx| {
                if s.dragging
                    && e.pressed_button == Some(MouseButton::Left)
                    && let Some(l) = &s.layout
                {
                    s.select(l.hit(e.position), true, w, cx)
                }
            }))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|s, _, _, _| s.dragging = false),
            )
            .on_mouse_up_out(
                MouseButton::Left,
                cx.listener(|s, _, _, _| s.dragging = false),
            )
            .on_scroll(cx.listener(|s, e: &ScrollEvent, _, cx| {
                if s.mode.multiline()
                    && let Some(l) = &s.layout
                {
                    let max = l
                        .rows
                        .iter()
                        .map(|r| f32::from(r.size(l.line).height))
                        .sum::<f32>()
                        - f32::from(l.bounds.size.height);
                    let next =
                        (s.scroll.y - e.delta.pixel_delta(l.line).y).clamp(px(0.), px(max.max(0.)));
                    if next != s.scroll.y {
                        s.scroll.y = next;
                        s.follow_caret = false;
                        cx.stop_propagation();
                        cx.notify()
                    }
                }
            }))
            .child(
                canvas(
                    |_, _, _| (),
                    move |bounds, _, w, cx| entity.update(cx, |s, cx| s.paint(bounds, w, cx)),
                )
                .size_full(),
            )
    }
}

#[cfg(test)]
mod shortcut_tests {
    use super::is_command_submit;
    #[test]
    fn shortcut_is_opt_in_and_never_intercepts_composition_or_normal_enter() {
        assert!(is_command_submit(true, false, "enter", true, false, false));
        assert!(!is_command_submit(
            false, false, "enter", true, false, false
        ));
        assert!(!is_command_submit(true, true, "enter", true, false, false));
        assert!(!is_command_submit(
            true, false, "enter", false, false, false
        ));
        assert!(!is_command_submit(true, false, "enter", true, true, false));
    }
}

#[cfg(test)]
mod ghost_motion_tests {
    use super::{Editor, InputMode};
    use gpui::TestAppContext;

    #[test]
    fn chunks_keep_timing_when_a_word_is_accepted_and_dismissal_blocks_accept() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(|w, cx| Editor::new("Text", InputMode::Multi, w, cx));
        w.update(|w, cx| {
            view.update(cx, |editor, cx| {
                editor.set_value("Start", w, cx);
                editor.set_ghost(" first", cx);
                let started = editor.ghost_chunks[0].started;
                editor.set_ghost(" first second", cx);
                assert_eq!(editor.ghost_chunks.len(), 2);
                assert_eq!(editor.ghost_chunks[0].started, started);
                assert!(editor.accept_ghost(true, w, cx));
                assert_eq!(editor.ghost.as_ref(), " second");
                assert_eq!(editor.ghost_chunks.len(), 1);
                editor.dismiss_ghost(cx);
                assert!(!editor.accept_ghost(false, w, cx));
                editor.set_value("New input", w, cx);
                assert!(editor.ghost.is_empty());
                assert!(editor.ghost_fade_out.is_none());
            })
        });
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}
